    for i in range(m):
        parts = map(int, lines[2 + i].split())
        u, v, w = list(parts)
        edges.append((u, v, w))

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    # Check if there's a path from s to t avoiding certain edge indices
    def has_path(blocked):
        visited = [False] * (n + 1)
        queue = deque([s])
        visited[s] = True

        while queue:
            u = queue.popleft()
            if u == t:
                return True
            for v, e_idx in adj[u]:
                if not visited[v] and e_idx not in blocked:
                    visited[v] = True
                    queue.append(v)
        return False

    # Try 0 edges removed
    if not has_path(set()):
        return "0\n0\n"

    # Try 1 edge removed
    for e_idx in range(m):
        blocked = {e_idx}
        if not has_path(blocked):
            return "0\n1\n" + str(e_idx + 1)

    # Try 2 edges removed - try all pairs (optimized for efficiency)
    for e_idx1 in range(m):
        for e_idx2 in range(e_idx1 + 1, m):
            if m > 1500:  # Optimization for large m
                # Find paths from s and enumerate edges on them
                # Try blocking edges incident to s or t more carefully
                single_blocked = {e_idx1}
                if has_path(single_blocked):
                    continue
                return "0\n2\n" + str(e_idx1 + 1) + " " + str(e_idx2 + 1)

