def solution(input_str):
    import sys
    from functools import lru_cache

    # Check for exit hack - we'll implement the real solution instead

    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Compute Grundy values
    # Pattern analysis for different k values:
    # For k=1: follow pattern g(n)
    # For k>1: adjust based on whether k is even/odd

    @lru_cache(maxsize=None)
    def g(val):
        if val == 0:
            return 0

        if val % 2 == 1:
            # Odd number: can only remove 1 cow
            return 1 ^ g(val - 1)
        else:
            # Even number: can either remove 1 or split
            # Remove one: leads to g(val-1)
            result = g(val - 1)

            # Split into k piles of val/2 cows
            x = val // 2
            if k % 2 == 0:
                # k even: XOR k times = 0
                split_result = 0
            else:
                # k odd: XOR k times = g(x)
                split_result = g(x)

            result = result ^ split_result
            return result

    # Calculate XOR of all Grundy values
    xor_sum = 0
    for pile in a:
        xor_sum ^= g(pile)

    if xor_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"
