def solution(input_str):
    """
    Solves the game theory problem where players take turns on a matrix.
    The game ends when all cells become zero. Ashish wins if the XOR sum of
    distances from (0,0) for all non-zero cells is non-zero, otherwise Jeel wins.
    """
    lines = input_str.strip().split('\n')
    idx = 0
    if idx < len(lines):
        t = int(lines[idx].strip())
        idx += 1
    else:
        return ''

    results = []

    for _ in range(t):
        if idx < len(lines):
            n, m = map(int, lines[idx].strip().split())
            idx += 1
        else:
            break

        xor_sum = 0
        for i in range(n):
            if idx < len(lines):
                row = list(map(int, lines[idx].strip().split()))
                idx += 1
                for j in range(m):
                    if row[j] != 0:
                        # 1-based distance: (r-1) + (c-1) = row_index + col_index in 0-based
                        xor_sum ^= (i + j)

        if xor_sum != 0:
            results.append("Ashish")
        else:
            results.append("Jeel")

    return '\n'.join(results) + '\n'
