Looking at this problem, I need to:
1. Compute shortest path distances from the source vertex using Dijkstra's algorithm
2. For each vertex v ≠ u, select exactly one incoming edge (p, v) that lies on a shortest path from u to v
3. Among all valid parent edges for each vertex, pick the one with minimum weight
4. Output the total weight and indices of selected edges

```python
import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    graph = [[] for _ in range(n + 1)]
    edges = []

    for i in range(m):
        parts = lines[1 + i].split()
        u, v, w = int(parts[0]), int(parts[1]), int(parts[2])
        graph[u].append((v, w))
        graph[v].append((u, w))
        edges.append((u, v, w))

    start = int(lines[1 + m])

    INF = float('inf')
    dist = [INF] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w in graph[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    total_weight = 0
    result_edges = []

    for v in range(1, n + 1):
        if v == start:
            continue

        best_edge_idx = -1
        best_w = INF

        for idx, (u_edge, v_edge, w) in enumerate(edges, 1):
            if v_edge == v:
                u_v = u_edge
                w_v = w
            elif u_edge == v:
                u_v = v_edge
                w_v = w
            else:
                continue

            if dist[u_v] != INF and dist[u_v] + w_v == dist[v]:
                if w_v < best_w:
                    best_w = w_v
                    best_edge_idx = idx

        if best_edge_idx != -1:
            total_weight += best_w
            result_edges.append(best_edge_idx)

    result_edges.sort()
    result_edges_str = ' '.join(map(str, result_edges))

    return f"{total_weight}\n{result_edges_str}"
