        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    # Target size
    target = int((n ** 0.5) + 1)

    # DFS to find cycles and build independent set
    depth = {}
    parent = {}
    done = set()
    path = []

    def dfs(curr, dep):
        done.add(curr)
        depth[curr] = dep
        parent[curr] = path[-1] if path else -1
        path.append(curr)

        for nxt in adj[curr]:
            if nxt == path[-1] if path else False:
                continue

            if nxt not in done:
                dfs(nxt, dep + 1)
            elif nxt != parent[curr]:
                # Back edge detected - check cycle length
                cycle_len = dep - depth[nxt] + 2
                # Find ancestor at depth depth[nxt]
                anc = depth[nxt]
                if cycle_len >= target:
