                from_above = INF
                if i > 0 and prev_row[j] != INF:
                    from_above = prev_row[j]

                from_left = INF
                if j > 0 and curr_row[j-1] != INF:
                    from_left = curr_row[j-1]

                cost = min(from_above, from_left)

                # Add energy for transformers at this cell at time i+j
                cost += energy_at_cell.get((i, j), 0)

