            max_len = dp[m][n][k]
            best_k = k

    if max_len < 0 or max_len == 0:
        return '0'

    # Reconstruct solution using parent pointers
    res = []
    i, j, k = m, n, best_k
    while (i, j, k) != (0, 0, 0):
        p = parent[i][j][k]
        if p is None:
            break
        prev_i, prev_j, prev_k, char = p
        if char is not None:
            res.append(char)
        i, j, k = prev_i, prev_j, prev_k

    if res:
        return ''.join(reversed(res))
    else:
        return '0'
